package ru.ryadom.calendar;
import android.app.*;import android.content.*;import android.text.InputType;import android.view.*;import android.widget.*;import org.json.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;
final class EventEditor {
 final MainActivity a;final Event before;final String token="edit-"+UUID.randomUUID();final List<String[]> targets=new ArrayList<>();final Map<String,JSONObject> accounts;final JSONObject data;
 EditText title,location,description,minutes;CheckBox none,allDay;Spinner calendar;TextView feedback;AlertDialog dialog;long start,end;boolean saving;
 EventEditor(MainActivity a,Event before){this.a=a;this.before=before;data=Store.read(a);accounts=Mirror.accounts(data);start=before==null?a.day.atTime(12,0).atZone(Event.ZONE).toInstant().toEpochMilli():before.start;end=before==null?start+3600000:before.end;}
 static void open(MainActivity a,Event before){if(before!=null&&(before.recurring||Mirror.isCopy(Store.read(a),before))){a.toast("Серии и автоматические копии редактируются в исходном календаре.");return;}if(before==null){new EventEditor(a,null).show();return;}JSONObject account=Mirror.accounts(Store.read(a)).get(before.source);if(account==null)return;a.toast("Загружаю встречу…");new Thread(()->{try{Event fresh=EventWrites.detail(a,account,before);a.runOnUiThread(()->{if(!a.isFinishing())new EventEditor(a,fresh).show();});}catch(Exception e){a.runOnUiThread(()->a.toast(message(e)));}},"event-details").start();}
 static String message(Exception e){return e instanceof Providers.Failure?e.getMessage():"Не удалось сохранить. Проверьте подключение и обновите календарь.";}
 EditText field(LinearLayout box,String name,String value,boolean single){box.addView(a.label(name,12,a.green,true));EditText edit=new EditText(a);edit.setTextSize(16);edit.setSingleLine(single);edit.setText(value);edit.setTag("editor-"+name);box.addView(edit);a.gap(box,8);return edit;}
 void show(){
  if(before!=null&&before.recurring){a.toast("Редактирование серии пока доступно у провайдера.");return;}
  for(JSONObject account:accounts.values()){if(!account.optBoolean("active",true))continue;String id=account.optString("id");JSONObject status=Store.object(data,"statuses").optJSONObject(id),cals=status==null?null:status.optJSONObject("calendars");if(cals==null)continue;Iterator<String> it=cals.keys();while(it.hasNext()){String cal=it.next();if(before!=null&&(!before.source.equals(id)||!before.calendar.equals(cal)))continue;if("device".equals(account.optString("type"))&&!DeviceWrites.writable(a,cal))continue;targets.add(new String[]{id,cal,CalendarStyle.name(data,id,cal)+" · "+("device".equals(account.optString("type"))?"Телефон":account.optString("type").equals("ews")?"Exchange":"Яндекс")});}}
  if(targets.isEmpty()){a.toast("Нет доступных календарей для записи. Подключите календарь; для системных разрешите запись в настройках Пекла.");return;}
  LinearLayout box=a.column();box.setPadding(a.dp(20),a.dp(8),a.dp(20),a.dp(12));calendar=new Spinner(a);List<String> names=new ArrayList<>();for(String[] t:targets)names.add(t[2]);calendar.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,names));box.addView(calendar);a.gap(box,12);
  title=field(box,"Название",before==null?"":before.title,true);allDay=new CheckBox(a);allDay.setText("Весь день");allDay.setChecked(before!=null&&before.allDay);box.addView(allDay);
  Button from=a.button("",()->pick(true)),to=a.button("",()->pick(false));from.setTag("editor-start");to.setTag("editor-end");box.addView(from);box.addView(to);Runnable times=()->{DateTimeFormatter fmt=DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm");from.setText("Начало · "+Instant.ofEpochMilli(start).atZone(Event.ZONE).format(fmt));to.setText("Конец · "+Instant.ofEpochMilli(end).atZone(Event.ZONE).format(fmt));};renderTimes=times;times.run();box.addView(a.label("Время по Москве. Для события на весь день конец — следующий день.",11,0xff7d886f,false));a.gap(box,12);
  none=new CheckBox(a);none.setText("Без напоминания");none.setChecked(before!=null&&before.reminderMinutes<0);box.addView(none);minutes=field(box,"Напомнить за … минут",before==null?"15":""+Math.max(0,before.reminderMinutes),true);minutes.setInputType(InputType.TYPE_CLASS_NUMBER);minutes.setEnabled(!none.isChecked());none.setOnCheckedChangeListener((v,on)->minutes.setEnabled(!on));
  location=field(box,"Место",before==null?"":before.location,true);description=field(box,"Описание",before==null?"":before.description,false);description.setMinLines(2);feedback=a.label("",12,0xffa34839,false);box.addView(feedback);ScrollView scroll=new ScrollView(a);scroll.addView(box);
  dialog=new AlertDialog.Builder(a).setTitle(before==null?"Новая встреча":"Изменить встречу").setView(scroll).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->save()));dialog.show();dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);dialog.getWindow().setLayout(-1,-2);
 }
 Runnable renderTimes;
 void pick(boolean beginning){ZonedDateTime date=Instant.ofEpochMilli(beginning?start:end).atZone(Event.ZONE);new DatePickerDialog(a,(v,y,m,d)->new TimePickerDialog(a,(clock,h,min)->{long value=LocalDate.of(y,m+1,d).atTime(h,min).atZone(Event.ZONE).toInstant().toEpochMilli();if(beginning)start=value;else end=value;renderTimes.run();},date.getHour(),date.getMinute(),true).show(),date.getYear(),date.getMonthValue()-1,date.getDayOfMonth()).show();}
 void save(){if(saving)return;Event e=new Event();try{String[] target=targets.get(calendar.getSelectedItemPosition());e.source=target[0];e.calendar=target[1];e.title=title.getText().toString().trim();e.location=location.getText().toString();e.description=description.getText().toString();e.allDay=allDay.isChecked();e.start=e.allDay?Instant.ofEpochMilli(start).atZone(Event.ZONE).toLocalDate().atStartOfDay(Event.ZONE).toInstant().toEpochMilli():start;e.end=e.allDay?Instant.ofEpochMilli(end).atZone(Event.ZONE).toLocalDate().atStartOfDay(Event.ZONE).toInstant().toEpochMilli():end;e.reminderMinutes=none.isChecked()?-1:Integer.parseInt(minutes.getText().toString());if(e.title.isEmpty()||e.end<=e.start||e.reminderMinutes< -1||e.reminderMinutes>525600)throw new IllegalArgumentException();}catch(Exception error){feedback.setText("Проверьте название, начало/конец и напоминание (0–525600 минут).");return;}
  if(!Sync.busy.compareAndSet(false,true)){feedback.setText("Дождитесь окончания обновления и нажмите сохранить.");return;}saving=true;dialog.setCancelable(false);dialog.getButton(-1).setEnabled(false);dialog.getButton(-2).setEnabled(false);feedback.setText("Сохраняю…");new Thread(()->{try{Event saved=EventWrites.save(a,accounts.get(e.source),e.calendar,before,e,token);cache(a,before,saved);a.runOnUiThread(()->{dialog.dismiss();a.day=Instant.ofEpochMilli(saved.start).atZone(Event.ZONE).toLocalDate();a.render();});}catch(Exception error){a.runOnUiThread(()->feedback.setText(message(error)));}finally{Sync.busy.set(false);a.runOnUiThread(()->{saving=false;dialog.setCancelable(true);dialog.getButton(-1).setEnabled(true);dialog.getButton(-2).setEnabled(true);});Notices.schedule(a);TodayWidget.refresh(a);Sync.async(a);}},"event-save").start();
 }
 static void cache(Context c,Event before,Event saved){Store.edit(c,d->{JSONArray out=new JSONArray();JSONArray events=Store.array(d,"events");for(int i=0;i<events.length();i++){Event current=Event.from(events.getJSONObject(i));if((before!=null&&current.key().equals(before.key()))||(saved!=null&&current.key().equals(saved.key())))continue;out.put(current.json());}if(saved!=null){out.put(saved.json());JSONObject seen=Store.object(d,"seen");seen.put(saved.key(),System.currentTimeMillis());d.put("seen",seen);}d.put("events",out);});}
}
